function ProfileEditor({user,endpoint,staff=false,permissionDefs=[],currentUser=null,onClose,onSaved,onError}){const [form,setForm]=useState({full_name:user.full_name||'',email:user.email||'',phone:user.phone||'',role_id:user.role==='Manager'?2:3,permissions:user.permissions||[]}),[busy,setBusy]=useState(false);const canEditPermissions=staff&&user.role!=='Administrator'&&Number(user.id)!==Number(currentUser?.id);const permissionGroups=permissionDefs.reduce((a,p)=>((a[p.module_name]??=[]).push(p),a),{});async function submit(e){e.preventDefault();setBusy(true);try{const payload={full_name:form.full_name,email:form.email,phone:form.phone,...(staff&&user.role!=='Administrator'?{role_id:Number(form.role_id)}:{})};const r=await api.put(endpoint,payload);if(canEditPermissions)await api.put(endpoint+'/permissions',{permissions:form.permissions});onSaved(r.data.user||r.data.customer)}catch(e){onError(e.response?.data?.error||'Unable to save profile details')}finally{setBusy(false)}}return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><form className="product-modal user-modal" onSubmit={submit}><div className="modal-heading"><div><span className="eyebrow">ACCOUNT DETAILS</span><h2>{staff?'Edit staff details':'Edit profile'}</h2></div><button type="button" className="icon-button" onClick={onClose}><X/></button></div><div className="form-grid"><label>Full name<input required maxLength="160" value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>Email<input type="email" required={!endpoint.includes('customer')} maxLength="190" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Phone<input maxLength="40" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label>{staff&&user.role!=='Administrator'&&<label>Account level<select value={form.role_id} onChange={e=>setForm({...form,role_id:Number(e.target.value)})}><option value={2}>Manager</option><option value={3}>Staff</option></select></label>}</div>{canEditPermissions&&<section className="staff-permission-editor"><div><h3>Staff permissions</h3><p>Select the sections and actions this staff member can access.</p></div><div className="permission-grid">{Object.entries(permissionGroups).map(([module,items])=><fieldset key={module}><legend>{module}</legend>{items.map(permission=><label key={permission.code}><input type="checkbox" checked={form.permissions.includes(permission.code)} onChange={e=>setForm({...form,permissions:e.target.checked?[...form.permissions,permission.code]:form.permissions.filter(code=>code!==permission.code)})}/>{permission.label}</label>)}</fieldset>)}</div></section>}<div className="modal-actions"><button type="button" className="button button-outline" disabled={busy} onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>{busy?'Saving...':'Save profile'}</button></div></form></div>}
function UserManager({rows,onReload,onError,onAction,canManage,canAudit,currentUser}){const [editingUser,setEditingUser]=useState(null),[creatingUser,setCreatingUser]=useState(false);const [activity,setActivity]=useState(null),[activityLoading,setActivityLoading]=useState(false),[accountEmailSent,setAccountEmailSent]=useState(false);const [filterText,setFilterText]=useState(''),[filterStatus,setFilterStatus]=useState('');const filtered=rows.filter(u=>`${u.full_name} ${u.email||''} ${u.phone||''} ${u.staff_position||''} ${u.role}`.toLowerCase().includes(filterText.toLowerCase())&&(!filterStatus||u.status===filterStatus));const [permissions,setPermissions]=useState([]),[open,setOpen]=useState(false),[showPass,setShowPass]=useState(''),[form,setForm]=useState({full_name:'',email:'',phone:'',role_id:3,permissions:[]});useEffect(()=>{api.get('/users').then(r=>{setPermissions(r.data.permissions||[])}).catch(e=>onError(e.response?.data?.error||'Unable to load permission definitions'))},[]);const groups=Object.groupBy?Object.groupBy(permissions,p=>p.module_name):permissions.reduce((a,p)=>((a[p.module_name]??=[]).push(p),a),{});async function viewActivity(u){setActivity({user:u,logs:[]});setActivityLoading(true);try{const r=await api.get(`/users/${u.id}/activity`);setActivity({user:u,logs:r.data.activity||[]})}catch(e){onError(e.response?.data?.error||'Unable to load user activity')}finally{setActivityLoading(false)}}function save(e){e.preventDefault();onAction({title:'Review new staff account',description:'Check the identity, account level and permissions before creating this account.',preview:[{label:'Name',value:form.full_name},{label:'Email',value:form.email||'Not provided'},{label:'Phone',value:form.phone||'Not provided'},{label:'Account level',value:Number(form.role_id)===2?'Manager':'Staff'},{label:'Permissions',value:form.permissions.length?form.permissions.join(', '):'Role defaults'}],confirmLabel:'Create staff account',onConfirm:async()=>{const submitted={...form};setOpen(false);setForm({full_name:'',email:'',phone:'',role_id:3,permissions:[]});setCreatingUser(true);api.post('/users',submitted).then(r=>{setAccountEmailSent(Boolean(r.data.email_sent));setShowPass(r.data.temporary_password);onReload()}).catch(e=>onError(e.response?.data?.error||'Unable to create user')).finally(()=>setCreatingUser(false));return true}})}return <><div className="panel table-panel"><div className="toolbar"><div><h2>System users</h2><p>Assign each staff member only the access they need.</p></div>{canManage&&<button className="button button-primary" onClick={()=>setOpen(true)}><Plus size={15}/> Add user</button>}</div><RecordsFilterBar search={filterText} onSearch={setFilterText} placeholder="Search name, email, phone or role" status={filterStatus} onStatus={setFilterStatus} statusOptions={[...new Set(rows.map(u=>u.status))].map(x=>({value:x,label:x}))}/><div className="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>PHONE</th><th>POSITION</th><th>ACCOUNT LEVEL</th><th>STATUS</th><th>ACCOUNT ACTIONS</th></tr></thead><tbody>{filtered.length?filtered.map(u=><tr key={u.id}><td><b>{u.full_name}</b></td><td>{u.email||'â€”'}</td><td>{u.phone||'â€”'}</td><td>{u.staff_position||'â€”'}</td><td>{u.role}</td><td><span className="status-pill status-good"><i/>{u.status}</span></td><td><div className="table-actions">{canManage&&<button className="button button-small button-outline" onClick={()=>setEditingUser(u)}>Edit details</button>}{canAudit&&<button className="button button-small button-outline" onClick={()=>viewActivity(u)}>View log</button>}{canManage&&u.email&&<button className="button button-small button-outline" onClick={()=>onAction({title:'Review password reset email',description:'A new temporary password will be generated and emailed to this user. The current password will stop working immediately, and the user must change the temporary password on next sign-in.',preview:[{label:'User',value:u.full_name},{label:'Delivery address',value:u.email},{label:'Delivery method',value:'Email'}],warning:'The password changes only if the email is delivered successfully.',confirmLabel:'Send reset email',onConfirm:async()=>{try{await api.post(`/users/${u.id}/reset-password`,{});onReload();onError('Password reset email sent to '+u.email);return true}catch(e){onError(e.response?.data?.error||'Unable to send password reset email');return false}}})}>Reset by email</button>}</div></td></tr>):<tr><td colSpan="7" className="table-empty">No users match these filters.</td></tr>}</tbody></table></div></div>{open&&<div className="modal-backdrop" onClick={()=>setOpen(false)}><form className="product-modal user-modal" onSubmit={save} onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><span className="eyebrow">ACCESS CONTROL</span><h2>Create staff account</h2></div><button type="button" className="icon-button" onClick={()=>setOpen(false)}><X/></button></div><div className="form-grid"><label>Full name<input required value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})}/></label><label>Account level<select value={form.role_id} onChange={e=>setForm({...form,role_id:Number(e.target.value)})}><option value="2">Manager</option><option value="3">Staff</option></select></label><label>Email<input type="email" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Phone<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label></div><div className="permission-grid">{Object.entries(groups).map(([module,ps])=><fieldset key={module}><legend>{module}</legend>{ps.map(p=><label key={p.code}><input type="checkbox" checked={form.permissions.includes(p.code)} onChange={e=>setForm({...form,permissions:e.target.checked?[...form.permissions,p.code]:form.permissions.filter(x=>x!==p.code)})}/>{p.label}</label>)}</fieldset>)}</div><div className="modal-actions"><button type="button" className="button button-outline" onClick={()=>setOpen(false)}>Cancel</button><button className="button button-primary">Review account creation</button></div></form></div>}{editingUser&&<ProfileEditor user={editingUser} endpoint={`/users/${editingUser.id}`} staff permissionDefs={permissions} currentUser={currentUser} onClose={()=>setEditingUser(null)} onSaved={()=>{setEditingUser(null);onReload();onError('Staff details updated')}} onError={onError}/>}{showPass&&<div className="modal-backdrop" onClick={()=>setShowPass('')}><div className="login-modal" onClick={e=>e.stopPropagation()}><h2>Temporary password</h2><p>{accountEmailSent?'The temporary password was emailed to the new user. Share it only if the email could not be delivered. They must change it at first sign in.':'SMTP is not configured or delivery failed. Share this temporary password with the new user through a secure channel. They must change it at first sign in.'}</p><input readOnly value={showPass}/><button className="button button-primary full-button" onClick={()=>setShowPass('')}>Done</button></div></div>}{activity&&<div className="modal-backdrop import-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setActivity(null)}}><section className="import-modal-card user-activity-modal" role="dialog" aria-modal="true"><div className="modal-head"><div><div className="eyebrow">ACCOUNT ACTIVITY</div><h2>{activity.user.full_name}</h2><p>Recent system events performed by or recorded against this account.</p></div><button type="button" className="icon-button" onClick={()=>setActivity(null)} aria-label="Close activity log"><X size={18}/></button></div>{activityLoading?<div className="table-empty">Loading account activity?</div>:<div className="table-wrap"><table><thead><tr><th>TIME</th><th>EVENT</th><th>RECORD</th><th>DETAILS</th></tr></thead><tbody>{activity.logs.length?activity.logs.map(log=><tr key={log.id}><td>{new Date(log.created_at).toLocaleString()}</td><td><b>{log.action}</b><small className="subcell">By {log.actor_name||'System'}</small></td><td>{log.entity_type}{log.entity_id?` #${log.entity_id}`:''}</td><td><small>{typeof log.details==='string'?log.details:JSON.stringify(log.details||{})}</small></td></tr>):<tr><td colSpan="4" className="table-empty">No activity has been recorded for this account yet.</td></tr>}</tbody></table></div>}<div className="modal-actions"><button className="button button-outline" onClick={()=>setActivity(null)}>Close</button></div></section></div>}</>}
function ProductModal({form,setForm,onClose,onSave,editing=false,canAdjustStock=false}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="product-modal" onSubmit={e=>{e.preventDefault();onSave()}} onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><span className="eyebrow">PRODUCT MANAGEMENT</span><h2>{editing?'Edit product and box prices':'Add a product'}</h2></div><button type="button" className="icon-button" onClick={onClose} aria-label="Close product form"><X size={19}/></button></div>{editing&&<p className="muted-note">Product code: <b>{form.code}</b></p>}<div className="form-grid"><label>Product name<input required maxLength="180" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label>{!editing&&canAdjustStock&&<label>Opening stock (boxes)<input required type="number" min="0" step="1" value={form.opening_stock_boxes??0} onChange={e=>setForm({...form,opening_stock_boxes:Number(e.target.value)})}/></label>}<label>Units per box<input required type="number" min="1" value={form.units_per_box} onChange={e=>setForm({...form,units_per_box:Number(e.target.value)})}/></label><label>Selling price per box (TZS)<input required type="number" min="0" step="0.01" value={form.box_price} onChange={e=>setForm({...form,box_price:Number(e.target.value)})}/></label><label>Buying price per box (TZS)<input required type="number" min="0" step="0.01" value={form.cost_price} onChange={e=>setForm({...form,cost_price:Number(e.target.value)})}/></label><label className="span-two">Description<input maxLength="2000" value={form.description||''} onChange={e=>setForm({...form,description:e.target.value})}/></label></div><div className="check-row"><label><input type="checkbox" checked={Boolean(form.allow_individual)} onChange={e=>setForm({...form,allow_individual:e.target.checked})}/> Allow individual item sales</label><label><input type="checkbox" checked={Boolean(form.is_public)} onChange={e=>setForm({...form,is_public:e.target.checked})}/> Show on customer catalogue and website</label></div><div className="modal-actions"><button type="button" className="button button-outline" onClick={onClose}>Cancel</button><button type="submit" className="button button-primary">Review product</button></div></form></div>}

function Pos({rows,loading,settings,editProforma,onUpdate,onCreate,onSubmitPayment,onAction,onError}){const [cart,setCart]=useState([]),[term,setTerm]=useState(''),[notice,setNotice]=useState('');const matches=rows.filter(p=>`${p.name} ${p.code}`.toLowerCase().includes(term.toLowerCase()));const unitPrice=p=>p.unit==='item'?Number(p.box_price)/Math.max(1,Number(p.units_per_box||1)):Number(p.box_price);const lineTotal=p=>unitPrice(p)*Number(p.quantity||0);const total=cart.reduce((sum,p)=>sum+lineTotal(p),0);const availableUnits=p=>Math.max(0,Number(p.stock_units||0));const selectedUnits=p=>Number(p.quantity||0)*(p.unit==='item'?1:Number(p.units_per_box||1));const insufficient=p=>selectedUnits(p)>availableUnits(p);const cartHasInsufficient=cart.some(insufficient);function addProduct(product){const current=cart.find(x=>Number(x.id)===Number(product.id)),used=current?selectedUnits(current):0,perBox=Math.max(1,Number(product.units_per_box||1));if(used+perBox>availableUnits(product)){setNotice(`Insufficient stock: ${product.name} has ${Math.floor(availableUnits(product)/perBox)} full box(es) available.`);return}setNotice('');setCart(currentCart=>{const existing=currentCart.find(x=>Number(x.id)===Number(product.id));return existing?currentCart.map(x=>x===existing?{...x,quantity:Number(x.quantity||0)+1}:x):[...currentCart,{...product,quantity:1,unit:'box'}]})}useEffect(()=>{if(editProforma){setCart((editProforma.items||[]).map(i=>({id:Number(i.product_id),name:i.product_name,code:i.product_code,box_price:Number(i.box_price),units_per_box:Number(i.units_per_box),allow_individual:Boolean(Number(i.allow_individual)),quantity:Number(i.quantity),unit:i.unit})));setNotice(`Editing unpaid proforma ${editProforma.proforma_reference}. Add products, change quantities or remove lines, then review and save.`)}},[editProforma?.id]);function updateLine(index,changes){setCart(current=>current.map((p,i)=>i===index?{...p,...changes}:p))}function removeLine(i){const p=cart[i];onAction({title:'Remove point-of-sale line',description:'This removes the selected product from the unpaid proforma being edited.',preview:[{label:'Product',value:p.name},{label:'Code',value:p.code},{label:'Quantity',value:`${p.quantity} ${p.unit}`}],danger:true,confirmLabel:'Remove line',onConfirm:()=>{setCart(current=>current.filter((_,j)=>j!==i));return true}})}function reviewSale(){if(!cart.length){onError('Add at least one product before reviewing the proforma.');return}onAction({title:editProforma?'Review unpaid proforma changes':'Review point-of-sale proforma',description:'Verify products, quantities, units and total before saving this unpaid proforma.',invoice:values=>({settings,reference:editProforma?.proforma_reference||'DRAFT-PROFORMA',status:'UNPAID DRAFT',customer:{name:values.customer_name||editProforma?.customer_name||'Walk-in customer',email:values.customer_email||'',phone:values.customer_phone||''},date:new Date().toISOString(),items:cart.map(p=>({product_name:p.name,product_code:p.code,quantity_label:`${p.quantity} ${p.unit}`,unit_price_snapshot:unitPrice(p),line_total:lineTotal(p)})),total,totalLabel:'Amount due'}),invoiceOnly:true,fields:editProforma?[]:[{name:'customer_name',label:'Customer name (optional)',type:'text',maxLength:160,defaultValue:''},{name:'customer_email',label:'Customer email (optional)',type:'email',maxLength:190,defaultValue:''},{name:'customer_phone',label:'Customer phone (optional)',type:'text',maxLength:40,defaultValue:''}],confirmLabel:editProforma?'Save proforma changes':'Create proforma',onConfirm:async values=>{const customer={full_name:values.customer_name||'',email:values.customer_email||'',phone:values.customer_phone||''};const data=editProforma?await onUpdate(editProforma.id,cart):await onCreate(cart,customer);setCart([]);setNotice(`Proforma ${data.reference} saved. Submit payment for Finance review when ready.`);onAction({title:'Review POS payment submission',description:'Submit payment details for Finance review. The proforma remains unpaid until Finance approves it.',preview:[{label:'Proforma',value:data.reference},{label:'Amount',value:money(data.grand_total)},{label:'Inventory effect',value:'Stock changes only after Finance approves payment'}],fields:[{name:'payment_method',label:'Payment method',type:'select',required:true,defaultValue:'cash',options:[{value:'cash',label:'Cash'},{value:'bank',label:'Bank transfer'},{value:'mobile_money',label:'Mobile money'},{value:'card',label:'Card'},{value:'other',label:'Other'}]},{name:'transaction_reference',label:'Transaction reference (optional)',type:'text',maxLength:120,defaultValue:''}],confirmLabel:'Submit payment for review',onConfirm:async v=>{try{const ok=await onSubmitPayment(data,v);if(ok)setNotice(`Payment for proforma ${data.reference} submitted to Finance.`);return ok}catch(e){onError(e.response?.data?.error||'Payment submission failed');return false}}});return false}})}return <div className="pos-layout"><div className="panel pos-products"><div className="toolbar"><div><h2>Choose products</h2><p>Click a product to increase its quantity. Add or remove products before the proforma is paid.</p></div></div><label className="searchbox pos-search"><Search size={16}/><input value={term} onChange={e=>setTerm(e.target.value)} placeholder="Search by name or product code"/></label>{loading?<div className="table-empty">Loading products...</div>:<div className="pos-product-list">{matches.map(p=>{const selected=cart.find(x=>Number(x.id)===Number(p.id)),availableBoxes=Math.floor(availableUnits(p)/Math.max(1,Number(p.units_per_box||1))),outOfStock=availableUnits(p)<Number(p.units_per_box||1);return <button key={p.id} className={`pos-product ${outOfStock?'pos-product-unavailable':''}`} disabled={outOfStock} onClick={()=>addProduct(p)}><span className="product-symbol"><Package size={18}/></span><span><b>{p.name}</b><small>{p.code} ? {p.units_per_box} per box ? {availableBoxes} box(es) available</small></span><span><b>{money(p.box_price)}</b><small>per box</small></span>{selected&&<b className="pos-selected-count">In cart: {selected.quantity}</b>}{outOfStock?<span className="pos-stock-warning">OUT OF STOCK</span>:<Plus size={17}/>}</button>})}</div>}</div><div className="panel cart-panel"><div className="panel-head"><div><h2>{editProforma?'Edit unpaid transaction':'Transaction preview'}</h2><p>{editProforma?`Proforma ${editProforma.proforma_reference} is unpaid. Its lines can be added, changed or removed before a new payment is submitted.`:'Review the products and total. Finance approval is required before stock is deducted.'}</p></div><ShoppingCart size={18}/></div>{notice&&<div className="inline-alert">{notice}</div>}{cart.length?<div className="cart-list">{cart.map((p,i)=><div className="cart-item" key={p.id}><div><b>{p.name}</b><small>{p.code}</small></div><select value={p.unit} onChange={e=>updateLine(i,{unit:e.target.value})}><option value="box">Box</option>{p.allow_individual&&<option value="item">Individual item</option>}</select><input type="number" min="1" value={p.quantity} onChange={e=>updateLine(i,{quantity:Number(e.target.value)})}/><div className="pos-cart-availability"><b>{money(lineTotal(p))}</b><small className={insufficient(p)?'pos-stock-warning':'status-good'}>{insufficient(p)?`INSUFFICIENT ? ${Math.max(0,availableUnits(p)-selectedUnits(p))} units short`:`Selected ${p.quantity} ? ${Math.max(0,availableUnits(p)-selectedUnits(p))} units left`}</small></div><button className="icon-button" onClick={()=>removeLine(i)} aria-label={`Remove ${p.name}`}><Trash2 size={14}/></button></div>)}<div className="cart-total"><span>Subtotal preview</span><b>{money(total)}</b></div><button className="button button-primary full-button" onClick={reviewSale} disabled={cartHasInsufficient}>{cartHasInsufficient?'Insufficient stock':'Review proforma'} <ArrowRight size={16}/></button></div>:<div className="cart-empty"><span className="cart-empty-icon"><ShoppingCart size={20}/></span><b>Your preview is empty</b><span>Add products to view the selling-unit options.</span></div>}</div></div>}
export default App;

